"/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Plus Jakarta Sans', sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

:root {
    --bg-dark: #070a13;
    --bg-darker: #04060b;
    --card-bg: rgba(15, 23, 42, 0.65);
    --card-border: rgba(255, 255, 255, 0.08);
    --primary-gradient: linear-gradient(135deg, #00f2fe 0%, #4facfe 100%);
    --accent-gradient: linear-gradient(135deg, #8a2be2 0%, #4a00e0 100%);
    --accent-glow: rgba(0, 242, 254, 0.25);
    --danger-gradient: linear-gradient(135deg, #ff5b5b 0%, #d11a2a 100%);
    --text-primary: #f8fafc;
    --text-secondary: #94a3b8;
    --text-muted: #64748b;
    --success-color: #10b981;
}

body {
    background-color: var(--bg-dark);
    color: var(--text-primary);
    min-height: 100vh;
    overflow-x: hidden;
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 2rem 1rem;
}

/* Background Ambient Glows */
.glass-bg {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: -3;
    background: radial-gradient(circle at 50% 50%, #0d1527 0%, var(--bg-darker) 100%);
}

.glow {
    position: fixed;
    width: 600px;
    height: 600px;
    border-radius: 50%;
    filter: blur(150px);
    z-index: -2;
    opacity: 0.15;
    pointer-events: none;
    animation: float 20s ease-in-out infinite alternate;
}

.glow-1 {
    top: -200px;
    left: -200px;
    background: #00f2fe;
}

.glow-2 {
    bottom: -200px;
    right: -200px;
    background: #8a2be2;
    animation-delay: -10s;
}

@keyframes float {
    0% {
        transform: translate(0, 0) scale(1);
    }
    100% {
        transform: translate(100px, 50px) scale(1.1);
    }
}

/* App Container */
.app-container {
    width: 100%;
    max-width: 1200px;
    z-index: 1;
}

